// â”€â”€â”€ TTS LANG MAP â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const TTS_LANG = {
  English:"en-IN", à¤¹à¤¿à¤‚à¤¦à¥€:"hi-IN", à²•à²¨à³à²¨à²¡:"kn-IN",
  à®¤à®®à®¿à®´à¯:"ta-IN", à°¤à±†à°²à±à°—à±:"te-IN", à´®à´²à´¯à´¾à´³à´‚:"ml-IN",
};
const STT_LANG = {
  English:"en-IN", à¤¹à¤¿à¤‚à¤¦à¥€:"hi-IN", à²•à²¨à³à²¨à²¡:"kn-IN",
  à®¤à®®à®¿à®´à¯:"ta-IN", à°¤à±†à°²à±à°—à±:"te-IN", à´®à´²à´¯à´¾à´³à´‚:"ml-IN",
};

// â”€â”€â”€ SPEAK HELPER â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// Picks the best available voice with graceful fallbacks.
function pickVoice(langCode) {
  const voices = window.speechSynthesis.getVoices();
  if (!voices.length) return null;
  const base = langCode.split("-")[0]; // e.g. "kn" from "kn-IN"
  // Priority 1: exact locale match (e.g. "kn-IN")
  let v = voices.find(x => x.lang === langCode);
  // Priority 2: same language prefix (e.g. starts with "kn")
  if (!v) v = voices.find(x => x.lang.startsWith(base));
  // Priority 3: Indian English as fallback for scripts without a TTS voice
  if (!v) v = voices.find(x => x.lang === "en-IN");
  // Priority 4: any English voice
  if (!v) v = voices.find(x => x.lang.startsWith("en"));
  return v || null;
}

function doSpeak(text, langCode, onEnd) {
  if (!window.speechSynthesis) return;
  window.speechSynthesis.cancel();
  // Strip markdown / emoji that sound bad when read aloud
  const clean = text.replace(/[*_~`#âš ï¸ðŸ‘‹âœ“âœ”ï¸ðŸ’ŠðŸ”¬ðŸ’¬ðŸš¨ðŸ‘¤ðŸ¥ðŸ’§ðŸš¶ðŸ˜´ðŸ¥¦ðŸ§¼ðŸ”¥ðŸ‘£ðŸ©º]/gu, "").trim();
  const utt = new SpeechSynthesisUtterance(clean);
  utt.lang = langCode || "en-IN";
  utt.rate = 0.92;
  utt.pitch = 1.05;
  const voice = pickVoice(utt.lang);
  if (voice) utt.voice = voice;
  if (onEnd) { utt.onend = onEnd; utt.onerror = onEnd; }
  window.speechSynthesis.speak(utt);
}

// Public helper â€” waits for voices to be ready before speaking.
function speakText(text, langCode, onEnd) {
  if (!window.speechSynthesis) return;
  const voices = window.speechSynthesis.getVoices();
  if (voices.length > 0) {
    doSpeak(text, langCode, onEnd);
  } else {
    // Voices not yet loaded â€” wait for the browser event
    const handler = () => {
      window.speechSynthesis.removeEventListener("voiceschanged", handler);
      doSpeak(text, langCode, onEnd);
    };
    window.speechSynthesis.addEventListener("voiceschanged", handler);
  }
}

function TypingDots() {
  return <div style={{ display:"flex", gap:5, padding:"4px 0" }}>{[0,1,2].map(i=><div key={i} style={{ width:7, height:7, borderRadius:"50%", background:C.accent, animation:`typingDot 1.2s ${i*0.2}s ease-in-out infinite` }}/>)}</div>;
}

// â”€â”€â”€ CHAT MESSAGE with TTS button â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function ChatMsg({ msg, ttsLang }) {
  const isUser = msg.role === "user";
  const [speaking, setSpeaking] = useState(false);
  const [hover, setHover] = useState(false);

  const handleSpeak = () => {
    if (speaking) {
      window.speechSynthesis.cancel();
      setSpeaking(false);
      return;
    }
    if (!window.speechSynthesis) return;
    setSpeaking(true);
    speakText(
      msg.content,
      ttsLang || "en-IN",
      () => setSpeaking(false)
    );
    // Also handle error via a safety timeout fallback
    if (window.speechSynthesis) {
      const origErr = window.speechSynthesis.onerror;
      window.speechSynthesis.onerror = () => { setSpeaking(false); if(origErr) origErr(); };
    }
  };

  // Stop speaking when component unmounts
  useEffect(() => () => { if(speaking) window.speechSynthesis.cancel(); }, []);

  return (
    <div style={{ display:"flex", flexDirection:isUser?"row-reverse":"row", gap:9, marginBottom:14, animation:"msgIn 0.3s ease both" }}>
      {!isUser && (
        <div style={{ width:32, height:32, borderRadius:10, background:`linear-gradient(135deg,${C.accent},#009E5A)`, display:"flex", alignItems:"center", justifyContent:"center", fontSize:15, flexShrink:0, marginTop:2 }}>ðŸ©º</div>
      )}
      <div style={{ maxWidth:"80%", display:"flex", flexDirection:"column", alignItems:isUser?"flex-end":"flex-start" }}>
        <div style={{ padding:"11px 14px", borderRadius:isUser?"14px 14px 3px 14px":"14px 14px 14px 3px", background:isUser?`linear-gradient(135deg,${C.blue}22,${C.accent}18)`:C.bubbleBot, border:`1.5px solid ${isUser?C.blue+"33":C.border}`, fontSize:13, color:C.text, lineHeight:1.65, whiteSpace:"pre-wrap" }}>
          {msg.content}
        </div>
        {/* Time + TTS row */}
        <div style={{ display:"flex", alignItems:"center", gap:6, marginTop:4, flexDirection:isUser?"row-reverse":"row" }}>
          <div style={{ fontSize:10, color:C.muted }}>{msg.time}</div>
          {/* TTS button â€” shown for both user and bot messages */}
          <button
            onClick={handleSpeak}
            onMouseEnter={()=>setHover(true)}
            onMouseLeave={()=>setHover(false)}
            title={speaking?"Stop speaking":"Read aloud"}
            style={{
              background: speaking ? `${C.accent}30` : hover ? `${C.muted}20` : "transparent",
              border: `1px solid ${speaking ? C.accent : hover ? C.muted+"60" : "transparent"}`,
              borderRadius:8, width:24, height:24, cursor:"pointer",
              display:"flex", alignItems:"center", justifyContent:"center",
              fontSize:12, transition:"all 0.2s", flexShrink:0,
            }}
          >
            {speaking ? (
              <span style={{ display:"flex", gap:2, alignItems:"flex-end", height:12 }}>
                {[3,5,4,6,3].map((h,i)=>(
                  <div key={i} style={{ width:2, height:h, background:C.accent, borderRadius:2, animation:`typingDot 0.8s ${i*0.1}s ease-in-out infinite` }}/>
                ))}
              </span>
            ) : (
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke={hover?C.textSub:C.muted} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                <polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"/>
                <path d="M15.54 8.46a5 5 0 0 1 0 7.07"/>
                <path d="M19.07 4.93a10 10 0 0 1 0 14.14"/>
              </svg>
            )}
          </button>
        </div>
      </div>
    </div>
  );
}

// â”€â”€â”€ MIC BUTTON â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function MicButton({ onResult, onInterim, lang, disabled }) {
  const [status, setStatus] = useState("idle"); // idle | requesting | listening | error | unsupported
  const recogRef = useRef(null);

  // Check support on mount
  useEffect(() => {
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SR) setStatus("unsupported");
  }, []);

  const startListening = async () => {
    if (disabled || status === "listening") return;

    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SR) { setStatus("unsupported"); return; }

    // Request mic permission explicitly first
    try {
      setStatus("requesting");
      await navigator.mediaDevices.getUserMedia({ audio: true });
    } catch (e) {
      setStatus("error");
      setTimeout(() => setStatus("idle"), 2000);
      return;
    }

    try {
      const recog = new SR();
      recog.continuous = false;
      recog.interimResults = true;
      recog.maxAlternatives = 1;
      recog.lang = STT_LANG[lang] || "en-IN";

      recog.onstart = () => setStatus("listening");

      recog.onresult = (e) => {
        let interim = "";
        let final = "";
        for (let i = e.resultIndex; i < e.results.length; i++) {
          const t = e.results[i][0].transcript;
          if (e.results[i].isFinal) final += t;
          else interim += t;
        }
        if (interim && onInterim) onInterim(interim);
        if (final) onResult(final);
      };

      recog.onerror = (e) => {
        setStatus(e.error === "not-allowed" ? "error" : "idle");
        if (e.error === "not-allowed") setTimeout(() => setStatus("idle"), 2500);
      };

      recog.onend = () => setStatus("idle");

      recogRef.current = recog;
      recog.start();
    } catch(e) {
      setStatus("idle");
    }
  };

  const stopListening = () => {
    recogRef.current?.stop();
    setStatus("idle");
  };

  useEffect(() => () => recogRef.current?.abort(), []);

  const isListening = status === "listening";
  const isRequesting = status === "requesting";
  const isError = status === "error";
  const isUnsupported = status === "unsupported";

  const bgColor = isListening
    ? `linear-gradient(135deg,${C.danger},#C41E3A)`
    : isError ? `${C.danger}22`
    : isRequesting ? `${C.warn}22`
    : C.cardHover;

  const borderColor = isListening ? C.danger : isError ? C.danger : isRequesting ? C.warn : C.border;

  return (
    <div style={{ display:"flex", flexDirection:"column", alignItems:"center", gap:2, flexShrink:0 }}>
      <button
        onClick={isListening ? stopListening : startListening}
        disabled={disabled || isUnsupported || isRequesting}
        title={
          isUnsupported ? t.voiceNotSupported :
          isError ? "Mic permission denied. Please allow microphone access." :
          isRequesting ? "Requesting mic access..." :
          isListening ? "Tap to stop" : "Tap to speak"
        }
        style={{
          width:44, height:44, borderRadius:12,
          border:`1.5px solid ${borderColor}`,
          background: bgColor,
          cursor: disabled||isUnsupported||isRequesting ? "default" : "pointer",
          display:"flex", alignItems:"center", justifyContent:"center",
          transition:"all 0.25s",
          boxShadow: isListening ? `0 0 0 4px ${C.danger}33, 0 4px 16px ${C.danger}44` : "none",
          opacity: isUnsupported ? 0.3 : disabled ? 0.5 : 1,
          position:"relative",
        }}
      >
        {/* Ping ring when listening */}
        {isListening && (
          <div style={{ position:"absolute", inset:-5, borderRadius:15, border:`2px solid ${C.danger}55`, animation:"ping 1s ease-out infinite", pointerEvents:"none" }}/>
        )}

        {isRequesting ? (
          <div style={{ width:16, height:16, borderRadius:"50%", border:`2px solid ${C.warn}44`, borderTopColor:C.warn, animation:"spin 0.8s linear infinite" }}/>
        ) : isError ? (
          <span style={{ fontSize:16 }}>ðŸš«</span>
        ) : isListening ? (
          <span style={{ display:"flex", gap:2, alignItems:"flex-end", height:16 }}>
            {[3,7,5,9,4,7,3].map((h,i)=>(
              <div key={i} style={{ width:2.5, height:h, background:"#fff", borderRadius:2, animation:`typingDot 0.65s ${i*0.09}s ease-in-out infinite` }}/>
            ))}
          </span>
        ) : (
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke={C.textSub} strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
            <path d="M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z"/>
            <path d="M19 10v2a7 7 0 0 1-14 0v-2"/>
            <line x1="12" y1="19" x2="12" y2="23"/>
            <line x1="8" y1="23" x2="16" y2="23"/>
          </svg>
        )}
      </button>

      {/* Status label under mic */}
      <div style={{ fontSize:8, fontWeight:700, letterSpacing:0.3, color:
        isListening ? C.danger :
        isRequesting ? C.warn :
        isError ? C.danger : C.muted,
        textAlign:"center", lineHeight:1.2, maxWidth:44,
      }}>
        {isListening ? t.micListening : isRequesting ? t.micAllow : isError ? t.micDenied : isUnsupported ? t.micNA : t.mic}
      </div>
    </div>
  );
}

function ChatScreen({ username }) {
  const { t, lang } = useLang();
  const suggestions = SUGG_DATA[lang] || SUGG_DATA.English;
  const ttsLang = TTS_LANG[lang] || "en-IN";

  const [messages, setMessages] = useState([{
    id:1, role:"assistant",
    time:new Date().toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"}),
    content: `${t.hi} ${username}! ðŸ‘‹ ${t.medBotIntro}\n\n${t.notSubstitute}`
  }]);
  const [input, setInput] = useState("");
  const [isTyping, setIsTyping] = useState(false);
  const [showSugg, setShowSugg] = useState(true);
  const [history, setHistory] = useState([]);
  const [autoSpeak, setAutoSpeak] = useState(true);
  const bottomRef = useRef(null);

  useEffect(()=>{ bottomRef.current?.scrollIntoView({behavior:"smooth"}); },[messages,isTyping]);

  // Keep a ref to the current ttsLang so async callbacks always get the latest value
  const ttsLangRef = useRef(ttsLang);
  useEffect(() => { ttsLangRef.current = ttsLang; }, [ttsLang]);

  // Preload voices on mount â€” trigger getVoices() repeatedly until they arrive
  useEffect(() => {
    if (!window.speechSynthesis) return;
    const load = () => window.speechSynthesis.getVoices();
    load();
    window.speechSynthesis.onvoiceschanged = load;
    // Some browsers (Chrome) need a small delay
    const t1 = setTimeout(load, 300);
    const t2 = setTimeout(load, 800);
    return () => { clearTimeout(t1); clearTimeout(t2); };
  }, []);

  const sendMessage = async(text) => {
    const content=(text||input).trim(); if(!content)return;
    const time=new Date().toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"});
    setMessages(prev=>[...prev,{id:Date.now(),role:"user",content,time}]);
    setInput(""); setIsTyping(true); setShowSugg(false);
    const newHistory=[...history,{role:"user",content}]; setHistory(newHistory);
    try {
      const res=await fetch(`http://${window.location.hostname}:3001/api/chat`,{
        method:"POST",headers:{"Content-Type":"application/json"},
        body:JSON.stringify({message:content,language:LANG_TO_API[lang]||lang})
      });
      const data=await res.json();
      const botContent=data.response||"I'm having trouble. Please try again.";
      const botMsg = {id:Date.now()+1,role:"assistant",content:botContent,time:new Date().toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"})};
      setMessages(prev=>[...prev,botMsg]);
      setHistory(prev=>[...prev,{role:"assistant",content:botContent}]);
      // Auto-speak bot reply if enabled
      if(autoSpeak) speakText(botContent, ttsLangRef.current);
    } catch {
      setMessages(prev=>[...prev,{id:Date.now()+1,role:"assistant",content:"âš ï¸ Connection error. Please try again.",time:new Date().toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"})}]);
    } finally { setIsTyping(false); }
  };

  const [interimText, setInterimText] = useState("");

  const handleVoiceInput = (transcript) => {
    setInterimText("");
    setInput(prev => {
      const base = prev.trim();
      return base ? base + " " + transcript : transcript;
    });
  };

  const handleInterim = (interim) => setInterimText(interim);

  const clearChat = () => {
    window.speechSynthesis?.cancel();
    setMessages([{id:Date.now(),role:"assistant",time:new Date().toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"}),content:`${t.hi} ${username}! ðŸ‘‹`}]);
    setHistory([]); setShowSugg(true);
  };

  return (
    <div style={{ display:"flex", flexDirection:"column", height:"100%" }}>
      {/* Header */}
      <div style={{ padding:"10px 16px", background:C.card, borderBottom:`1px solid ${C.border}`, display:"flex", alignItems:"center", gap:10, flexShrink:0 }}>
        <div style={{ width:36, height:36, borderRadius:11, background:`linear-gradient(135deg,${C.accent},#009E5A)`, display:"flex", alignItems:"center", justifyContent:"center", fontSize:16 }}>ðŸ©º</div>
        <div style={{ flex:1 }}>
          <div style={{ fontSize:14, fontWeight:800, color:C.text }}>{t.medBotAI}</div>
          <div style={{ display:"flex", alignItems:"center", gap:4 }}>
            <div style={{ width:6, height:6, borderRadius:"50%", background:C.accent }}/>
            <span style={{ fontSize:10, color:C.textSub }}>{t.medBotOnline}</span>
          </div>
        </div>
        {/* Auto-speak toggle */}
        <button
          onClick={()=>{ setAutoSpeak(p=>!p); if(autoSpeak) window.speechSynthesis?.cancel(); }}
          title={autoSpeak?"Auto-speak ON (tap to turn off)":"Auto-speak OFF"}
          style={{ background:autoSpeak?`${C.accent}20`:C.cardHover, border:`1px solid ${autoSpeak?C.accent:C.border}`, borderRadius:8, padding:"6px 8px", cursor:"pointer", display:"flex", alignItems:"center", gap:4, transition:"all 0.2s" }}
        >
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke={autoSpeak?C.accent:C.muted} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"/>
            <path d="M15.54 8.46a5 5 0 0 1 0 7.07"/>
            <path d="M19.07 4.93a10 10 0 0 1 0 14.14"/>
          </svg>
          <span style={{ fontSize:9, fontWeight:700, color:autoSpeak?C.accent:C.muted }}>{autoSpeak?t.auto : t.off}</span>
        </button>
        <button onClick={clearChat} style={{ background:C.cardHover, border:`1px solid ${C.border}`, borderRadius:8, padding:"7px 10px", cursor:"pointer", fontSize:13, color:C.textSub }}>ðŸ—‘ï¸</button>
      </div>

      {/* Messages */}
      <div style={{ flex:1, overflowY:"auto", padding:"14px 14px 8px" }}>
        <div style={{ textAlign:"center", marginBottom:12 }}>
          <span style={{ display:"inline-block", padding:"4px 12px", background:C.accentDim, border:`1px solid ${C.accentGlow}`, borderRadius:20, fontSize:10, color:C.muted }}>ðŸ”’ {t.private}</span>
        </div>

        {/* TTS hint */}
        <div style={{ textAlign:"center", marginBottom:14 }}>
          <span style={{ display:"inline-flex", alignItems:"center", gap:5, padding:"5px 12px", background:`${C.blue}12`, border:`1px solid ${C.blue}30`, borderRadius:20, fontSize:10, color:C.textSub }}>
            <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke={C.blue} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"/><path d="M15.54 8.46a5 5 0 0 1 0 7.07"/></svg>
            {t.chatAudioHint}
          </span>
        </div>

        {messages.map(msg=><ChatMsg key={msg.id} msg={msg} ttsLang={ttsLang}/>)}
        {isTyping && (
          <div style={{ display:"flex", gap:9, marginBottom:14 }}>
            <div style={{ width:32, height:32, borderRadius:10, background:`linear-gradient(135deg,${C.accent},#009E5A)`, display:"flex", alignItems:"center", justifyContent:"center", fontSize:15 }}>ðŸ©º</div>
            <div style={{ padding:"11px 14px", background:C.bubbleBot, border:`1.5px solid ${C.border}`, borderRadius:"14px 14px 14px 3px" }}><TypingDots/></div>
          </div>
        )}
        {showSugg&&!isTyping&&(
          <div style={{ animation:"fadeUp 0.5s 0.3s ease both" }}>
            <div style={{ fontSize:11, color:C.muted, fontWeight:600, textTransform:"uppercase", letterSpacing:0.4, marginBottom:8 }}>{t.quickQuestions}</div>
            <div style={{ display:"flex", flexWrap:"wrap", gap:7 }}>
              {suggestions.map((s,i)=>(
                <button key={i} onClick={()=>sendMessage(s.text)}
                  style={{ display:"flex", alignItems:"center", gap:5, padding:"7px 11px", background:C.card, border:`1.5px solid ${C.border}`, borderRadius:20, fontSize:11, color:C.textSub, cursor:"pointer" }}
                  onMouseEnter={e=>{e.currentTarget.style.borderColor=C.accent;e.currentTarget.style.color=C.text;}}
                  onMouseLeave={e=>{e.currentTarget.style.borderColor=C.border;e.currentTarget.style.color=C.textSub;}}>
                  <span>{s.icon}</span><span>{s.text}</span>
                </button>
              ))}
            </div>
          </div>
        )}
        <div ref={bottomRef}/>
      </div>

      <div style={{ padding:"5px 14px", background:"#07111E", borderTop:`1px solid ${C.border}`, fontSize:10, color:C.muted, textAlign:"center", flexShrink:0 }}>{t.notSubstitute}</div>

      {/* Input area */}
      <div style={{ padding:"10px 12px 12px", background:C.card, borderTop:`1px solid ${C.border}`, flexShrink:0 }}>
        <div style={{ display:"flex", gap:7, alignItems:"flex-end" }}>
          {/* Mic button */}
          <MicButton onResult={handleVoiceInput} onInterim={handleInterim} lang={lang} disabled={isTyping}/>

          {/* Text input */}
          <div style={{ flex:1, position:"relative" }}>
            <textarea
              value={input}
              onChange={e=>setInput(e.target.value)}
              onKeyDown={e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();sendMessage();}}}
              placeholder={interimText ? "" : t.chatPlaceholder}
              rows={1}
              style={{ width:"100%", background:C.cardHover, border:`1.5px solid ${interimText?C.danger:input?C.accent:C.border}`, borderRadius:12, padding:"11px 14px", fontSize:13, color:C.text, resize:"none", lineHeight:1.5, maxHeight:90, overflow:"auto", transition:"border-color 0.2s", boxShadow:interimText?`0 0 0 3px ${C.danger}22`:input?`0 0 0 3px ${C.accentGlow}`:"none" }}
            />
            {interimText && (
              <div style={{ position:"absolute", top:"50%", transform:"translateY(-50%)", left:14, right:14, fontSize:13, color:C.muted, pointerEvents:"none", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>
                ðŸŽ¤ {interimText}...
              </div>
            )}
          </div>

          {/* Send button */}
          <button
            onClick={()=>sendMessage()}
            disabled={!input.trim()||isTyping}
            style={{ width:44, height:44, borderRadius:12, border:"none", background:input.trim()&&!isTyping?`linear-gradient(135deg,${C.accent},#009E5A)`:C.cardHover, cursor:input.trim()&&!isTyping?"pointer":"default", display:"flex", alignItems:"center", justifyContent:"center", fontSize:17, transition:"all 0.2s", flexShrink:0, boxShadow:input.trim()&&!isTyping?`0 4px 16px ${C.accentGlow}`:"none" }}
          >
            {isTyping
              ? <div style={{ width:14,height:14,borderRadius:"50%",border:`2px solid ${C.muted}`,borderTopColor:C.accent,animation:"spin 0.7s linear infinite" }}/>
              : <span style={{ color:input.trim()?"#021A0E":C.muted }}>âž¤</span>
            }
          </button>
        </div>
        <div style={{ fontSize:10, color:C.muted, marginTop:6, textAlign:"center" }}>
          {t.chatInputHint}
        </div>
      </div>
    </div>
  );
}

// â”€â”€â”€ EMERGENCY â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function EmergencyScreen() {
  const { t } = useLang();
  const [locShared, setLocShared] = useState(false); const [alertSent, setAlertSent] = useState(false);
  const services = [
    {icon:"ðŸš‘",label:t.ambulance,num:"108",color:C.danger},
    {icon:"ðŸ†˜",label:t.nationalEmergency,num:"112",color:C.orange},
    {icon:"ðŸ‘©â€âš•ï¸",label:t.womenSafety,num:"1091",color:C.purple},
    {icon:"ðŸ§’",label:t.childHelpline,num:"1098",color:C.blue},
    {icon:"â¤ï¸",label:t.healthHelpline,num:"104",color:C.teal},
    {icon:"â˜Žï¸",label:t.police,num:"100",color:C.warn},
  ];
  return (
    <div style={{ overflowY:"auto", padding:"16px 16px 8px", height:"100%" }}>
      <div style={{ textAlign:"center", marginBottom:18 }}>
        <div style={{ position:"relative", width:64, height:64, borderRadius:"50%", background:C.danger, display:"flex", alignItems:"center", justifyContent:"center", fontSize:28, margin:"0 auto 10px" }}>
          ðŸš¨<div style={{ position:"absolute", inset:-4, borderRadius:"50%", border:`2px solid ${C.danger}`, animation:"ping 1.5s infinite" }}/>
        </div>
        <div style={{ fontSize:18, fontWeight:800, color:C.text, marginBottom:4 }}>{t.emergencyAssistance}</div>
        <div style={{ fontSize:12, color:C.textSub }}>{t.tapToCall}</div>
      </div>
      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10, marginBottom:16 }}>
        {services.map((s,i)=>(
          <a key={i} href={`tel:${s.num}`}
            style={{ background:C.card, border:`2px solid ${s.color}44`, borderRadius:14, padding:"14px 10px", cursor:"pointer", display:"flex", flexDirection:"column", alignItems:"center", gap:6, transition:"all 0.2s", textDecoration:"none" }}
            onMouseEnter={e=>{e.currentTarget.style.background=`${s.color}15`;e.currentTarget.style.borderColor=s.color;}}
            onMouseLeave={e=>{e.currentTarget.style.background=C.card;e.currentTarget.style.borderColor=`${s.color}44`;}}>
            <span style={{ fontSize:26 }}>{s.icon}</span>
            <span style={{ fontSize:11, fontWeight:700, color:C.text }}>{s.label}</span>
            <span style={{ fontSize:16, fontWeight:800, color:s.color }}>{s.num}</span>
            <span style={{ fontSize:9, fontWeight:600, color:s.color, background:`${s.color}18`, padding:"2px 8px", borderRadius:10, border:`1px solid ${s.color}44` }}>TAP TO CALL</span>
          </a>
        ))}
      </div>
      <Divider label={t.safetyFeatures}/>
      <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
        <Card style={{ display:"flex", alignItems:"center", gap:12, cursor:"pointer" }} onClick={()=>setLocShared(p=>!p)}>
          <div style={{ width:38, height:38, borderRadius:10, background:locShared?`${C.accent}22`:C.cardHover, display:"flex", alignItems:"center", justifyContent:"center", fontSize:18, border:`1px solid ${locShared?C.accent:C.border}`, flexShrink:0 }}>ðŸ“</div>
          <div style={{ flex:1 }}><div style={{ fontSize:13, fontWeight:700, color:C.text }}>{t.shareGPS}</div><div style={{ fontSize:11, color:C.muted }}>{t.shareGPSDesc}</div></div>
          <div style={{ width:36, height:20, borderRadius:10, background:locShared?C.accent:C.border, position:"relative", transition:"background 0.3s", flexShrink:0 }}><div style={{ position:"absolute", top:2, left:locShared?"18px":"2px", width:16, height:16, borderRadius:"50%", background:"#fff", transition:"left 0.3s" }}/></div>
        </Card>
        <Card style={{ display:"flex", alignItems:"center", gap:12, cursor:"pointer" }} onClick={()=>{setAlertSent(true);setTimeout(()=>setAlertSent(false),3000);}}>
          <div style={{ width:38, height:38, borderRadius:10, background:alertSent?`${C.warn}22`:C.cardHover, display:"flex", alignItems:"center", justifyContent:"center", fontSize:18, border:`1px solid ${alertSent?C.warn:C.border}`, flexShrink:0 }}>ðŸ””</div>
          <div style={{ flex:1 }}><div style={{ fontSize:13, fontWeight:700, color:C.text }}>{t.sendAlert}</div><div style={{ fontSize:11, color:alertSent?C.warn:C.muted }}>{alertSent?t.alertSent:t.alertDesc}</div></div>
          {alertSent && <Badge color={C.warn}>{t.alertSent}</Badge>}
        </Card>
      </div>
    </div>
  );
}

