// â”€â”€â”€ ROOT APP â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
export default function JeevaRaksha() {
  console.log("JeevaRaksha component rendering");
  const [screen, setScreen] = useState("login");
  const [username, setUsername] = useState("");
  const [userEmail, setUserEmail] = useState("");
  const [tab, setTab] = useState("dashboard");
  const [lang, setLangState] = useState(localStorage.getItem("jr_lang") || "English");

  const setLang = useCallback((l) => {
    if(TRANSLATIONS[l]) {
      setLangState(l);
      localStorage.setItem("jr_lang", l);
    }
  }, []);

  const t = TRANSLATIONS[lang] || TRANSLATIONS.English;

  useEffect(() => {
    const style = document.createElement("style");
    style.textContent = GLOBAL_CSS;
    document.head.appendChild(style);
    return () => document.head.removeChild(style);
  }, []);

  const handleLogin = (name, email) => { setUsername(name); setUserEmail(email || ""); setScreen("app"); setTab("dashboard"); };
  const handleLogout = () => { setUsername(""); setUserEmail(""); setScreen("login"); };
  const NAV_TABS = ["dashboard","symptom","chat","emergency","profile"];

  const renderTab = () => {
    switch(tab) {
      case "dashboard": return <DashboardScreenV2 username={username} onNav={t=>setTab(t)}/>;
      case "symptom":   return <SymptomScreen onNav={t=>setTab(t)}/>;
      case "chat":      return <ChatScreen username={username}/>;
      case "emergency": return <EmergencyScreen/>;
      case "hospitals": return <HospitalsScreen/>;
      case "reminder":  return <ReminderScreen/>;
      case "library":   return <LibraryScreen/>;
      case "ayurveda":  return <AyurvedaScreen/>;
      case "outbreak":  return <OutbreakScreen/>;
      case "profile":   return <ProfileScreen username={username} userEmail={userEmail} onLogout={handleLogout}/>;
      default:          return <DashboardScreenV2 username={username} onNav={t=>setTab(t)}/>;
    }
  };

  return (
    <LangContext.Provider value={{ lang, t, setLang }}>
      <div style={{ minHeight:"100vh", background:"#040A14", display:"flex", alignItems:"center", justifyContent:"center", padding:16 }}>
        <style>{GLOBAL_CSS}</style>
        <div style={{ width:"100%", maxWidth:420, height:700, background:C.bg, borderRadius:26, border:`1px solid ${C.border}`, boxShadow:`0 32px 80px #00000090, 0 0 0 1px #ffffff06`, overflow:"hidden", display:"flex", flexDirection:"column", animation:"fadeIn 0.5s ease" }}>
          {screen==="login"    && <LoginScreen onLogin={handleLogin} onGoRegister={()=>setScreen("register")} onGoForgot={()=>setScreen("forgot")}/>}
          {screen==="register" && <RegisterScreen onRegister={handleLogin} onGoLogin={()=>setScreen("login")}/>}
          {screen==="forgot"   && <ForgotScreen onBack={()=>setScreen("login")}/>}
          {screen==="app" && <>
            <div style={{ flex:1, overflow:"hidden", display:"flex", flexDirection:"column" }}>{renderTab()}</div>
            <BottomNav active={NAV_TABS.includes(tab)?tab:"dashboard"} onNav={t=>setTab(t)}/>
          </>}
        </div>
      </div>
    </LangContext.Provider>
  );
}

